DROP TABLE IF EXISTS `sales_invoices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_invoices` (
  `id` char(36) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `tenant_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `invoice_number` varchar(50) NOT NULL,
  `customer_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `sales_order_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `delivery_note_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `warehouse_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `invoice_date` date NOT NULL,
  `due_date` date NOT NULL,
  `journal_entry_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `reference` varchar(100) DEFAULT NULL,
  `notes` text,
  `sub_total` decimal(18,2) NOT NULL DEFAULT '0.00',
  `tax_total` decimal(18,2) NOT NULL DEFAULT '0.00',
  `discount_total` decimal(18,2) NOT NULL DEFAULT '0.00',
  `grand_total` decimal(18,2) NOT NULL DEFAULT '0.00',
  `status` enum('draft','posted','paid','partially_paid','overdue','cancelled') NOT NULL DEFAULT 'draft',
  `is_inventory_impact` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` char(36) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `updated_by` char(36) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `customer_account_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `revenue_account_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `tax_account_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tenant_id` (`tenant_id`),
  KEY `customer_id` (`customer_id`),
  KEY `sales_order_id` (`sales_order_id`),
  KEY `delivery_note_id` (`delivery_note_id`),
  KEY `warehouse_id` (`warehouse_id`),
  KEY `journal_entry_id` (`journal_entry_id`),
  KEY `created_by` (`created_by`),
  KEY `updated_by` (`updated_by`),
  KEY `idx_si_customer_account` (`customer_account_id`),
  KEY `idx_si_revenue_account` (`revenue_account_id`),
  KEY `idx_si_tax_account` (`tax_account_id`),
  CONSTRAINT `sales_invoices_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_invoices_ibfk_2` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_invoices_ibfk_3` FOREIGN KEY (`sales_order_id`) REFERENCES `sales_orders` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `sales_invoices_ibfk_4` FOREIGN KEY (`delivery_note_id`) REFERENCES `delivery_notes` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `sales_invoices_ibfk_5` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `sales_invoices_ibfk_6` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `sales_invoices_ibfk_7` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `sales_invoices_ibfk_8` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

