/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_unicode_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'IGNORE_SPACE,STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE PROCEDURE `sp_Report_BankAccountLedger`(
    IN p_TenantId CHAR(36),
    IN p_BankAccountId CHAR(36),
    IN p_DateFrom DATE,
    IN p_DateTo DATE,
    IN p_Page INT,
    IN p_PageSize INT
  )
BEGIN
    DECLARE v_Offset INT DEFAULT 0;
    
    IF p_Page IS NULL OR p_Page < 1 THEN SET p_Page = 1; END IF;
    IF p_PageSize IS NULL OR p_PageSize < 1 THEN SET p_PageSize = 50; END IF;
    SET v_Offset = (p_Page - 1) * p_PageSize;
    
    DROP TEMPORARY TABLE IF EXISTS tmp;
    
    CREATE TEMPORARY TABLE tmp AS
    SELECT 
      bt.transaction_number,
      bt.transaction_date,
      bt.transaction_type,
      bt.description,
      bt.debit_amount,
      bt.credit_amount,
      bt.status,
      ba.account_name,
      ba.account_number
    FROM bank_transactions bt
    JOIN bank_accounts ba ON ba.id = bt.bank_account_id
    WHERE bt.tenant_id = p_TenantId
      AND (p_BankAccountId IS NULL OR bt.bank_account_id = p_BankAccountId)
      AND (p_DateFrom IS NULL OR bt.transaction_date >= p_DateFrom)
      AND (bt.transaction_date <= p_DateTo OR p_DateTo IS NULL);
    
    SELECT 
      COUNT(*) AS total_transactions,
      COALESCE(SUM(debit_amount), 0) AS total_debit,
      COALESCE(SUM(credit_amount), 0) AS total_credit
    FROM tmp;
    
    SELECT 
      transaction_number,
      transaction_date,
      transaction_type,
      description,
      debit_amount,
      credit_amount,
      status,
      account_name
    FROM tmp
    ORDER BY transaction_date DESC
    LIMIT p_PageSize OFFSET v_Offset;
    
    SELECT COUNT(*) AS total FROM tmp;
    
    DROP TEMPORARY TABLE tmp;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
