BEGIN DECLARE v_Offset INT DEFAULT 0;IF p_Page IS NULL OR p_Page<1 THEN SET p_Page=1;END IF;IF p_PageSize IS NULL OR p_PageSize<1 THEN SET p_PageSize=50;END IF;SET v_Offset=(p_Page-1)*p_PageSize;
DROP TEMPORARY TABLE IF EXISTS tmp;CREATE TEMPORARY TABLE tmp AS SELECT gr.receipt_number,gr.receipt_date,gr.total_amount,s.name AS supplier_name FROM GoodsReceipts gr LEFT JOIN suppliers s ON s.id=gr.supplier_id WHERE gr.tenant_id=p_TenantId AND gr.status='approved' AND NOT EXISTS(SELECT 1 FROM PurchaseInvoices pi WHERE pi.tenant_id=p_TenantId AND pi.goods_receipt_id=gr.id) AND (p_DateFrom IS NULL OR gr.receipt_date>=p_DateFrom) AND (gr.receipt_date<=p_DateTo OR p_DateTo IS NULL);
SELECT COUNT(*) AS total_gr,COALESCE(SUM(total_amount),0) AS total_unbilled FROM tmp;
SELECT receipt_number,receipt_date,supplier_name,total_amount FROM tmp ORDER BY receipt_date DESC LIMIT p_PageSize OFFSET v_Offset;
SELECT COUNT(*) AS total FROM tmp;DROP TEMPORARY TABLE tmp;END ;;
